"""Fused MoE LoRA apply kernel variants.

The CuTe kernel implementation lives in `moe.lora.kernel`; this module is
import-safe before the CuTe dump environment is configured (no cutlass
imports at module scope), mirroring how the other cubin families defer
their kernel imports until compile time.
"""

from dataclasses import dataclass


K_VEC = 8  # bf16 elements per 16-byte load
WARP_SIZE = 32

# ABI version for the route and tiled-MMA cubin keys. Bump whenever a kernel
# parameter list or the routing semantics change (e.g. the v2 move to
# adapter-space sort keys and dense sorted scratch): stale prebuilt bundles
# and cached JIT artifacts resolve by key, so an unchanged key would pair an
# old cubin with the new argument list.
LORA_SEG_ABI_VERSION = 2

# Tiled-MMA (prefill) tile shapes, swept on B200/H100 (tokens=2048 eager,
# rank 16): expand wants wide-N shallow-K tiles with 8 warps (the K extent is
# the adapter rank, so one k-step covers it); shrink is K-deep and keeps the
# narrow default with one extra pipeline stage. block_m also fixes the route
# kernel's block-schedule granularity.
LORA_MMA_BLOCK_M = 32


def lora_mma_block_n(kind: str, out_dim: int, rank: int = 0) -> int:
    """Shrink tiles cover the (small) rank in N; expand tiles run wide with
    8 warps at every rank (wide tiles with 4 warps spill catastrophically)."""
    if kind != "mma_shrink":
        return 128
    if out_dim <= 32:
        return 32
    if out_dim <= 64:
        return 64
    return 128


def lora_mma_block_k(kind: str, rank: int = 0) -> int:
    if kind == "mma_shrink":
        return 32
    # One k-step covers small ranks; deeper ranks pipeline 32-deep steps.
    return 16 if rank <= 16 else 32


def lora_mma_warps(kind: str, rank: int = 0) -> int:
    return 4 if kind == "mma_shrink" else 8


def lora_mma_stages(kind: str) -> int:
    return 3 if kind == "mma_shrink" else 2


@dataclass(frozen=True)
class MoeLoraFusedVariant:
    # Per-assignment GEMV kinds (decode): "shrink" | "expand_add" |
    # "expand_add_weighted". Tiled-MMA kinds (prefill, over the
    # (route, expert) block schedule): "mma_shrink" | "mma_expand_add" |
    # "mma_expand_add_weighted". "route" is the (route, expert) assignment
    # sort + block schedule feeding the MMA kinds; its dims are unused.
    kind: str
    in_dim: int  # shrink: K of the dot; expand: storage rank bucket
    out_dim: int  # shrink: storage rank bucket; expand: output columns
    top_k: int
    num_experts: int
    warps_per_block: int = 8
    # shrink: x rows are per-token (up) or per-assignment (down).
    x_per_assignment: bool = False
    topk_weight_dtype: str = "bf16"
    # Tile shape for the MMA kinds (zero on GEMV kinds).
    block_m: int = 0
    block_n: int = 0
    block_k: int = 0
    num_stages: int = 2

    @property
    def variant_key(self) -> str:
        if self.kind in ("route_count", "route_scatter"):
            tw_suffix = (
                f"_tw{self.topk_weight_dtype}"
                if self.kind == "route_scatter"
                else ""
            )
            return (
                f"lora_{self.kind}_tk{self.top_k}_e{self.num_experts}"
                f"_b{LORA_MMA_BLOCK_M}{tw_suffix}_v{LORA_SEG_ABI_VERSION}"
            )
        x_suffix = "_xasg" if self.x_per_assignment else ""
        weight_suffix = (
            f"_tw{self.topk_weight_dtype}" if self.kind.endswith("_weighted") else ""
        )
        tile_suffix = ""
        abi_suffix = ""
        if self.kind.startswith("mma_"):
            tile_suffix = (
                f"_m{self.block_m}n{self.block_n}k{self.block_k}"
                f"_s{self.num_stages}"
            )
            abi_suffix = f"_v{LORA_SEG_ABI_VERSION}"
        return (
            f"lora_{self.kind}_K{self.in_dim}_N{self.out_dim}"
            f"_tk{self.top_k}_e{self.num_experts}_w{self.warps_per_block}"
            f"{tile_suffix}{x_suffix}{weight_suffix}{abi_suffix}"
        )



def make_compile_args(variant: MoeLoraFusedVariant):
    if variant.kind.startswith("mma_"):
        from kestrel_kernels.moe.lora.mma_kernel import (
            make_compile_args as _mma_impl,
        )

        return _mma_impl(variant)
    from kestrel_kernels.moe.lora.kernel import make_compile_args as _impl

    return _impl(variant)


__all__ = ["MoeLoraFusedVariant", "make_compile_args"]
